describe('Product Sorting by Price (Low to High)', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com/');
  });

  it('should sort products by price in ascending order when selecting "Price (low to high)"', () => {
    // Login with standard user
    cy.get('#user-name').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    // Verify login successful and products are visible
    cy.get('[data-test="inventory-container"]').should('be.visible');
    cy.get('[data-test="inventory-list"]').should('be.visible');

    // Get initial prices to verify sorting later
    cy.get('[data-test="inventory-item"]').each(($item) => {
      const priceText = $item.find('[data-test="inventory-item-price"]').text();
      const price = parseFloat(priceText.replace('$', '').trim());
      cy.wrap(price).as('itemPrice');
    });

    // Verify initial prices are not sorted by price (e.g., Backpack is $19.99, Bike Light is $29.99)
    cy.get('[data-test="inventory-item"]').first().find('[data-test="inventory-item-price"]').should('contain', '$19.99');
    cy.get('[data-test="inventory-item"]').last().find('[data-test="inventory-item-price"]').should('contain', '$14.99');

    // Select "Price (low to high)" sort option
    cy.get('[data-test="product-sort-container"]').select('lohi');

    // Verify products are reordered by price in ascending order
    cy.get('[data-test="inventory-item"]').first().find('[data-test="inventory-item-price"]').should('contain', '$17.99');
    cy.get('[data-test="inventory-item"]').last().find('[data-test="inventory-item-price"]').should('contain', '$4.99');

    // Verify the first item is the cheapest
    cy.get('[data-test="inventory-item"]').first().find('[data-test="inventory-item-price"]').should('contain', '$1.99');
    cy.get('[data-test="inventory-item"]').first().find('[data-test="inventory-item-name"]').should('contain', 'Sauce Labs Bolt T-Shirt');
  });

  it('should handle edge case when sorting with no items or invalid sort option', () => {
    // Login with standard user
    cy.get('#user-name').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    // Verify products are visible before sorting
    cy.get('[data-test="inventory-list"]').should('be.visible');

    // Attempt to select an invalid sort option
    cy.get('[data-test="product-sort-container"]').select('invalid-option');

    // Verify the page does not crash and the sort dropdown retains its previous state or defaults
    cy.get('[data-test="product-sort-container"]').should('be.visible');
    cy.get('[data-test="inventory-list"]').should('be.visible');

    // Verify the first item still exists and the page is functional
    cy.get('[data-test="inventory-item"]').first().should('be.visible');
    cy.get('[data-test="inventory-item"]').first().find('[data-test="inventory-item-price"]').should('be.visible');

    // Verify the sort option did not change to an unexpected value
    cy.get('[data-test="product-sort-container"]').should('have.value', 'lohi');
  });
});
